# Writes src/scenes.json for "The Battle of Thoughts: Spiritual Warfare in Everyday Life", about 25 minutes, in the look of
# Becoming and The Price Of Being A Man. One narration clip per sentence.
# Reference: "Spiritual Warfare in Daily Life: The Battle of Thoughts" (Eternalised, YouTube U-uB_2xpXao). The user pasted its
# transcript and asked for a 25-minute video on the same topic; the script below is freshly written in my own words, following
# the same ideas and order. Quotations come only from public-domain texts (the Bible in the World English Bible or KJV, Milton,
# Marcus Aurelius in George Long's translation, Seneca in Gummere's); modern authors (St Paisios, Fr Lampert, Fr Kamel,
# Fr Ripperger, Evagrius's modern translators) are paraphrased, not quoted.
# Per sentence: th = picture themes (src/images.json), big = the key word shown as a large script accent, gap = silence after.
import json, hashlib
S = []
def s(text, th, big=None, gap=1.0):
    S.append(dict(id="s" + hashlib.sha1(text.encode()).hexdigest()[:10], text=text, th=th if isinstance(th, list) else [th], big=big, red=False, gap=round(gap * 1.15, 2)))
def ch(num, title, dur=4.4): S.append(dict(id=f"ch{sum(1 for x in S if 'card' in x) + 1}", card="chapter", num=num, title=title, len=dur))

# ---- opening: an ordinary day
s("You wake up tired, but the day is already calling, so you get up.", ["morning", "bed"], big="tired")
s("Before your feet touch the floor, your hand has found the phone.", ["morning"])
s("Other people's lives scroll past, brighter and easier than yours, and a small sting of envy settles in.", ["crowd", "portrait"], big="envy")
s("The news is full of scandal. You feel disgust, and then, quietly, a little pride. At least you are not like them.", ["crowd", "pride"], big="pride")
s("On the road, the traffic crawls, and you rehearse excuses for being late.", ["road", "city"])
s("Impatience turns into anger, and under your breath you curse the strangers around you.", ["road", "anger"], big="anger")
s("At lunch, the talk turns to money, and to the people who have too much of it, and to the people who are not in the room.", ["feast", "crowd"])
s("You join in. Not because you agree, but because you do not want to be left out.", ["feast"])
s("Back at work there is a colleague who is better looking, better liked, better paid. You work harder, and he barely notices you.", ["portrait", "clerk"], big="notices")
s("You help someone with a task, and when he forgets to thank you, you resent him for it.", ["clerk"])
s("In the evening a stranger catches your eye, and for a moment she is not a person to you, only something to want.", ["street", "crowd"], big="want")
s("When she looks back, you look away, as if she could read your mind.", ["street"])
s("On the way home you give a few coins to a man on the pavement. He says nothing, and you regret the coins.", ["beggar"], big="coins")
s("At home, one careless remark is enough. You snap, and you shut the door behind you.", ["door", "anger"], big="snap")
s("You eat too much, though you promised yourself you would not.", ["feast", "stilllife"])
s("The book you bought to change your life sits on the shelf, and you choose another episode instead.", ["book", "night"])
s("Late at night the thoughts of lust from earlier come back, and you give in to them. Then come shame and guilt.", ["night", "despair"], big="shame")
s("You wonder why you cannot be patient, and kind, and diligent, and why envy, anger and sloth keep winning.", ["thinker", "despair"])
s("Saint Paul knew the feeling: for what I want to do, I do not do; but what I hate, that I do.", ["saint", "book"], big="hate", gap=1.4)
s("You promise yourself that tomorrow will be different, and you fall asleep.", ["night", "bed"])
s("You wake up tired. Your hand finds the phone. And the cycle begins again.", ["morning"], big="cycle", gap=1.6)

# ---- I
ch("I", "Two worlds")
s("Saint Paisios, a monk of Mount Athos, taught that the whole of the spiritual life rests on our thoughts.", ["monk", "mountain"], big="thoughts")
